from pathlib import Path
import json,zipfile,subprocess,sys,time,os,shutil
root=Path('/content/drive/MyDrive/BullingerAblation');work=Path('/content/bullinger-ablation');work.mkdir(exist_ok=True)
subprocess.check_call([sys.executable,'-m','pip','install','-q','transformers==4.51.0','Pillow==12.2.0','numpy==2.2.6'])
plan=work/('sampling-control-plan-'+time.strftime('%Y%m%dT%H%M%SZ',time.gmtime()));plan.mkdir()
with zipfile.ZipFile(root/'input/experiment-code.zip') as z:
 for n in z.namelist():
  if n.startswith('plan/') and n.endswith('.json'):(plan/Path(n).name).write_bytes(z.read(n))
 (work/'prepare.py').write_bytes(z.read('prepare.py'))
script=work/'run_sampling_control.py'
script.write_text("\"\"\"Train one manifest, or evaluate a saved checkpoint on its fixed test set.\"\"\"\nimport argparse\nimport hashlib\nimport importlib.metadata\nimport json\nimport os\nfrom pathlib import Path\nimport random\nimport shutil\nimport sys\nimport time\nfrom prepare import audit, dump\n\n\ndef distance(a, b):\n    previous = list(range(len(b)+1))\n    for i, x in enumerate(a, 1):\n        current = [i]\n        for j, y in enumerate(b, 1):\n            current.append(min(current[-1]+1, previous[j]+1, previous[j-1]+(x != y)))\n        previous = current\n    return previous[-1]\n\n\ndef metrics(rows):\n    out = {}\n    for group in ['overall', 'de', 'la']:\n        subset = [r for r in rows if group == 'overall' or r['language'] == group]\n        chars = sum(len(r['reference']) for r in subset)\n        words = sum(len(r['reference'].split()) for r in subset)\n        ce = sum(distance(r['reference'], r['prediction']) for r in subset)\n        we = sum(distance(r['reference'].split(), r['prediction'].split()) for r in subset)\n        out[group] = dict(n=len(subset), character_errors=ce, reference_chars=chars, word_errors=we, reference_words=words, cer=ce/chars if chars else None, wer=we/words if words else None)\n    return out\n\n\ndef aligned_training_loss(logits, labels):\n    \"\"\"Decoder inputs are already shifted by VisionEncoderDecoderModel.\"\"\"\n    import torch.nn.functional as F\n    return F.cross_entropy(logits.float().reshape(-1, logits.shape[-1]),\n                           labels.to(logits.device).reshape(-1), ignore_index=-100)\n\n\ndef main():\n    p = argparse.ArgumentParser(description=__doc__)\n    p.add_argument('--manifest', type=Path, required=True)\n    p.add_argument('--out', type=Path, required=True)\n    p.add_argument('--model', default='microsoft/trocr-base-handwritten')\n    p.add_argument('--revision', default='main', help='Use immutable Hugging Face commit for cross-machine reproduction')\n    p.add_argument('--evaluate-only', action='store_true')\n    p.add_argument('--device', choices=['cuda', 'mps', 'cpu'], default='cuda')\n    p.add_argument('--epochs', type=int, default=5)\n    p.add_argument('--batch-size', type=int, default=2)\n    p.add_argument('--resume-from', type=Path)\n    p.add_argument('--lr', type=float, default=1e-5)\n    p.add_argument('--max-length', type=int, default=128)\n    args = p.parse_args()\n    if args.epochs < 1 or args.batch_size < 1 or args.max_length < 2 or args.lr <= 0:\n        raise ValueError('Invalid training parameters')\n    if args.out.exists():\n        raise ValueError('Output exists; choose a fresh run directory')\n    m = json.loads(args.manifest.read_text())\n    ep = args.manifest.parent / m['evaluation_file']\n    evaluation = json.loads(ep.read_text())\n    fingerprint = hashlib.sha256(json.dumps(evaluation, sort_keys=True).encode()).hexdigest()\n    if fingerprint != m['evaluation_sha256']:\n        raise ValueError('Evaluation manifest changed')\n    split = dict(train=m['train'], **evaluation)\n    if any(v for d in audit(split).values() for v in d.values()):\n        raise ValueError('Letter or line leakage')\n    for rows in split.values():\n        for r in rows:\n            if r['language'] not in ['de', 'la'] or not Path(r['image']).is_file() or not Path(r['text']).is_file():\n                raise ValueError(f'Invalid sample {r}')\n    os.environ['CUBLAS_WORKSPACE_CONFIG'] = ':4096:8'\n    import numpy as np\n    import torch\n    from PIL import Image\n    from transformers import TrOCRProcessor, VisionEncoderDecoderModel\n    seed = m['seed']\n    random.seed(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n    if torch.cuda.is_available():\n        torch.cuda.manual_seed_all(seed)\n    torch.use_deterministic_algorithms(True)\n    device = torch.device(args.device)\n    if args.device == 'cuda' and not torch.cuda.is_available():\n        raise RuntimeError('CUDA unavailable; use an explicit --device cpu/mps if desired')\n    completed_checkpoints = sorted(args.resume_from.glob('checkpoint_epoch*/complete.json'),key=lambda p:int(p.parent.name.replace('checkpoint_epoch',''))) if args.resume_from else []\n    if args.resume_from and not completed_checkpoints: raise ValueError('No complete epoch checkpoints')\n    checkpoint = completed_checkpoints[-1].parent if completed_checkpoints else None\n    source_model = checkpoint if args.resume_from else args.model\n    load_revision = None if args.resume_from else args.revision\n    processor = TrOCRProcessor.from_pretrained(source_model, revision=load_revision, use_fast=False)\n    model = VisionEncoderDecoderModel.from_pretrained(source_model, revision=load_revision).to(device)\n    tok = processor.tokenizer\n    for config in [model.config, model.generation_config]:\n        config.decoder_start_token_id = tok.cls_token_id\n        config.pad_token_id = tok.pad_token_id\n        config.eos_token_id = tok.sep_token_id\n    labels = {}\n    data_hash = hashlib.sha256()\n    for rows in split.values():\n        for r in rows:\n            text = Path(r['text']).read_text(encoding='utf-8').strip()\n            if not text:\n                raise ValueError('Empty reference')\n            ids = tok(text).input_ids\n            if len(ids) > args.max_length:\n                raise ValueError(f'Label would truncate ({len(ids)} tokens): {r[\"text\"]}; increase --max-length for ALL runs')\n            labels[r['image']] = ids\n            data_hash.update(Path(r['image']).read_bytes())\n            data_hash.update(text.encode())\n    resume_state = None\n    prior_history = []\n    if args.resume_from:\n        prior_cfg = json.loads((args.resume_from/'config.json').read_text())\n        if prior_cfg.get('training_loss') != 'explicit_aligned_seq2seq_ce_v1':\n            raise ValueError('Cannot resume misaligned training')\n        for key, value in dict(model=args.model, revision=args.revision, max_length=args.max_length, epochs=args.epochs, batch_size=args.batch_size, lr=args.lr, evaluation_sha256=fingerprint, dataset_sha256=data_hash.hexdigest(), manifest=m).items():\n            if prior_cfg[key] != value:\n                raise ValueError(f'Resume protocol mismatch: {key}')\n        if prior_cfg['versions'] != {x:importlib.metadata.version(x) for x in ['torch','transformers','Pillow','numpy']}:\n            raise ValueError('Resume library versions differ')\n        resume_state = torch.load(checkpoint/'training_state.pt', map_location='cpu', weights_only=False)\n        prior_history = [r for r in json.loads((args.resume_from/'history.json').read_text()) if r['epoch']<=resume_state['epoch']]\n        completed = resume_state['epoch']\n        if [r['epoch'] for r in prior_history] != list(range(1,completed+1)):\n            raise ValueError('Checkpoint and history disagree; do not silently resume')\n    args.out.mkdir(parents=True)\n    if args.resume_from:\n        # Completed parent checkpoints stay read-only.\n        dump(args.out/'history.json',prior_history)\n        for r in prior_history:\n            epoch=r['epoch']\n            for filename in [f'draws_epoch{epoch}.json',f'validation_epoch{epoch}.jsonl']:\n                src=args.resume_from/filename\n                if src.exists(): shutil.copy2(src,args.out/filename)\n        dump(args.out/'resume_provenance.json',dict(parent=str(args.resume_from),completed_epoch=resume_state['epoch'],replay='Restart incomplete next epoch from saved optimizer and RNG; source retained'))\n    cfg = {k: str(v) if isinstance(v, Path) else v for k, v in vars(args).items()}\n    cfg.update(training_loss='explicit_aligned_seq2seq_ce_v1', manifest=m, evaluation_sha256=fingerprint, dataset_sha256=data_hash.hexdigest(), resolved_model_commit=getattr(model.config, '_commit_hash', None), python=sys.version, versions={x: importlib.metadata.version(x) for x in ['torch','transformers','Pillow','numpy']}, normalization='strip only; case/punctuation retained; WER uses whitespace split', selection='minimum overall validation CER', sampling='natural without replacement; balanced/de70 weighted replacement; N draws per epoch')\n    dump(args.out/'config.json', cfg)\n    dump(args.out/'evaluation.json', evaluation)\n\n    class Dataset(torch.utils.data.Dataset):\n        def __len__(self):\n            return len(m['train'])\n        def __getitem__(self, i):\n            r = m['train'][i]\n            with Image.open(r['image']) as im:\n                pixels = processor(images=im.convert('RGB'), return_tensors='pt').pixel_values[0]\n            ids = labels[r['image']]\n            label = torch.tensor(ids + [tok.pad_token_id]*(args.max_length-len(ids)))\n            label[label == tok.pad_token_id] = -100\n            return pixels, label\n\n    @torch.no_grad()\n    def evaluate(rows, name):\n        model.eval()\n        predictions = []\n        for r in rows:\n            with Image.open(r['image']) as im:\n                pixels = processor(images=im.convert('RGB'), return_tensors='pt').pixel_values.to(device)\n            ids = model.generate(pixels, max_new_tokens=args.max_length, num_beams=1, do_sample=False)\n            ref = Path(r['text']).read_text(encoding='utf-8').strip()\n            pred = processor.batch_decode(ids, skip_special_tokens=True)[0].strip()\n            predictions.append(dict(**r, reference=ref, prediction=pred, character_errors=distance(ref,pred), word_errors=distance(ref.split(),pred.split()), reference_length=len(ref), prediction_length=len(pred), cer=distance(ref,pred)/len(ref), wer=distance(ref.split(),pred.split())/len(ref.split())))\n        with (args.out/(name+'.jsonl')).open('w', encoding='utf-8') as f:\n            for r in predictions:\n                f.write(json.dumps(r, ensure_ascii=False)+'\\n')\n        return metrics(predictions)\n\n    history = prior_history.copy()\n    best_record = min(history,key=lambda r:r['validation']['overall']['cer']) if history else None\n    best = best_record['validation']['overall']['cer'] if best_record else float('inf')\n    best_epoch = best_record['epoch'] if best_record else None\n    if not args.evaluate_only:\n        optimizer = torch.optim.AdamW(model.parameters(), lr=args.lr)\n        if resume_state:\n            optimizer.load_state_dict(resume_state['optimizer'])\n            torch.set_rng_state(resume_state['torch_rng'])\n            torch.cuda.set_rng_state_all(resume_state['cuda_rng'])\n            random.setstate(resume_state['python_rng'])\n            np.random.set_state(resume_state['numpy_rng'])\n            print(f\"RESUMING AFTER COMPLETED EPOCH {resume_state['epoch']}\",flush=True)\n        for epoch in range((resume_state['epoch']+1) if resume_state else 1, args.epochs+1):\n            generator = torch.Generator().manual_seed(seed+epoch)\n            n = len(m['train'])\n            target = m['target_de_probability']\n            if target is None:\n                draws = torch.randperm(n, generator=generator).tolist()\n            else:\n                counts = m['train_counts']\n                weights = torch.tensor([target/counts['de'] if r['language']=='de' else (1-target)/counts['la'] for r in m['train']], dtype=torch.double)\n                draws = torch.multinomial(weights,n,replacement=True,generator=generator).tolist()\n            dump(args.out/f'draws_epoch{epoch}.json', draws)\n            loader = torch.utils.data.DataLoader(Dataset(),batch_size=args.batch_size,sampler=draws,num_workers=0)\n            model.train()\n            total, seen = 0., 0\n            started = time.time()\n            for step, (pixels, label) in enumerate(loader, 1):\n                optimizer.zero_grad()\n                target_labels = label.to(device)\n                outputs = model(pixel_values=pixels.to(device), labels=target_labels)\n                loss = aligned_training_loss(outputs.logits, target_labels)\n                if not torch.isfinite(loss):\n                    raise RuntimeError('Nonfinite loss')\n                loss.backward()\n                torch.nn.utils.clip_grad_norm_(model.parameters(),1.)\n                optimizer.step()\n                total += loss.item()*len(label)\n                seen += len(label)\n                if step % 100 == 0:\n                    print(f'epoch={epoch} step={step}/{len(loader)} loss={total/seen:.5f}',flush=True)\n            val = evaluate(evaluation['validation'],f'validation_epoch{epoch}')\n            record = dict(epoch=epoch, loss=total/seen, seconds=time.time()-started, validation=val, unique_draws=len(set(draws)), de_draws=sum(m['train'][i]['language']=='de' for i in draws))\n            history.append(record)\n            # History is published only after all epoch files are saved.\n            with (args.out/'log.jsonl').open('a') as f:\n                f.write(json.dumps(record)+'\\n')\n            print(json.dumps(record),flush=True)\n            if val['overall']['cer'] < best:\n                best = val['overall']['cer']\n                best_epoch = epoch\n                # Selection is published after the complete epoch checkpoint.\n            # Full last state, including RNG, for diagnosis/recovery; no implicit resume.\n            checkpoint=args.out/f'checkpoint_epoch{epoch}'\n            checkpoint.mkdir()\n            model.save_pretrained(checkpoint)\n            processor.save_pretrained(checkpoint)\n            torch.save(dict(epoch=epoch,optimizer=optimizer.state_dict(),torch_rng=torch.get_rng_state(),cuda_rng=torch.cuda.get_rng_state_all() if torch.cuda.is_available() else [],python_rng=random.getstate(),numpy_rng=np.random.get_state()),checkpoint/'training_state.pt')\n            dump(checkpoint/'complete.json',dict(epoch=epoch,best_epoch=best_epoch,best_validation_cer=best))\n            dump(args.out/'history.json',history)\n        del model\n        if device.type == 'cuda':\n            torch.cuda.empty_cache()\n        best_path=args.out/f'checkpoint_epoch{best_epoch}'\n        if not best_path.exists(): best_path=args.resume_from/f'checkpoint_epoch{best_epoch}'\n        model = VisionEncoderDecoderModel.from_pretrained(best_path).to(device)\n    test = evaluate(evaluation['test'],'test_predictions')\n    dump(args.out/'results.json',dict(size=m['size'],strategy=m['strategy'],seed=seed,evaluation_sha256=fingerprint,best_epoch=best_epoch,best_validation_cer=best if history else None,test=test,evaluate_only=args.evaluate_only))\n\n\nif __name__ == '__main__':\n    main()\n")
subprocess.run([sys.executable,'-m','py_compile',str(script)],check=True)
sys.path.insert(0,str(work))
from prepare import audit
natural=json.loads((plan/'n10000_natural_s42.json').read_text());balanced=json.loads((plan/'n10000_balanced_s42.json').read_text())
assert natural['train']==balanced['train'] and natural['seed']==balanced['seed']==42
assert natural['target_de_probability'] is None and balanced['target_de_probability']==.5
cfg=json.loads((root/'runs_scale_weights_restart_v1/n10000_natural_s42_20261011T212741Z/config.json').read_text())
evaluation=json.loads((plan/'evaluation.json').read_text())
import hashlib
assert hashlib.sha256(json.dumps(evaluation,sort_keys=True).encode()).hexdigest()==cfg['evaluation_sha256']==natural['evaluation_sha256']==balanced['evaluation_sha256']
assert not any(v for g in audit(dict(train=natural['train'],**evaluation)).values() for v in g.values())
needed={str(Path(r[k]).relative_to(work)) if Path(r[k]).is_absolute() else str(Path(r[k])) for rows in [natural['train'],*evaluation.values()] for r in rows for k in ['image','text']}
missing={n for n in needed if not (work/n).is_file()}
print('CONTROL VERIFIED: SAME 10000 UNIQUE LINES; FIXED EVALUATION; MISSING FILES',len(missing),flush=True)
for name in ['dataset-baseline.zip','dataset-additional.zip']:
 with zipfile.ZipFile(root/'input'/name) as z:
  chosen=[i for i in z.infolist() if i.filename in missing]
  assert all((work/i.filename).resolve().is_relative_to(work.resolve()) for i in chosen)
  assert shutil.disk_usage(work).free>sum(i.file_size for i in chosen)+4*1024**3
  for j,i in enumerate(chosen,1):
   z.extract(i,work)
   if j%1000==0:print('RESTORING',name,j,'/',len(chosen),flush=True)
  missing.difference_update(i.filename for i in chosen)
assert not missing
candidates=[p for p in root.glob('runs_sampling_control_v1/*/n10000_natural_s42') if list(p.glob('checkpoint_epoch*/complete.json'))]
resume_parent=max(candidates,key=lambda p:max(int(q.parent.name.replace('checkpoint_epoch','')) for q in p.glob('checkpoint_epoch*/complete.json'))) if candidates else None
print('RESUME NATURAL FROM',resume_parent,flush=True)
parent=root/'runs_sampling_l4_complete_v1'/time.strftime('%Y%m%dT%H%M%SZ',time.gmtime());parent.mkdir(parents=True)
(parent/'protocol.json').write_text(json.dumps(dict(arms=['natural','balanced'],seed=42,initialization='same pretrained revision; no warm start or optimizer reset',checkpoint='independent completed epoch directories',evaluation_sha256=natural['evaluation_sha256'],script_sha256=hashlib.sha256(script.read_bytes()).hexdigest(),settings={k:cfg[k] for k in ['model','revision','epochs','batch_size','lr','max_length']}),indent=2))
for strategy in ['natural','balanced']:
 out=parent/('n10000_'+strategy+'_s42')
 cmd=[sys.executable,'-u',str(script),'--manifest',str(plan/('n10000_'+strategy+'_s42.json')),'--out',str(out)]
 if strategy=='natural' and resume_parent:cmd.extend(['--resume-from',str(resume_parent)])
 for k in ['model','revision','epochs','batch_size','lr','max_length']:cmd.extend(['--'+k.replace('_','-'),str(cfg[k])])
 print('STARTING CONTROL ARM',strategy,out,flush=True)
 with subprocess.Popen(cmd,cwd=work,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True) as job:
  for line in job.stdout:print(line,end='',flush=True)
  assert job.wait()==0,'Arm failed; inspect epoch checkpoints before resuming'
 print('COMPLETED ARM',strategy,(out/'results.json').read_text(),flush=True)
print('BOTH SAMPLING ARMS COMPLETE',parent,flush=True)
